const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const visibilityIcon='<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>';
export function cellSidebarMarkup({title,tracking=false}){return `<aside class="cell-rail" aria-label="Observation controls">
<div class="cell-rail-scroll">
<header class="cell-rail-heading"><h1>${escape(title)}</h1><label class="cell-toggle cell-dual-toggle"><span>Two views</span><input id="cell-dual" type="checkbox" role="switch" aria-controls="cell-viewers" aria-label="Two views"></label></header>
<section class="cell-layers" aria-label="Wavelength layers"><div class="cell-section-heading"><h2>Wavelengths</h2><button id="cell-add-wavelength" type="button" aria-label="Add layer" title="Add another wavelength layer" disabled>＋ Add</button></div>
<section class="cell-layer-card cell-base-layer" aria-label="Layer 1"><div class="cell-layer-title"><h3>Layer 1</h3><button type="button" class="cell-layer-visible" aria-label="Layer 1 visibility" aria-pressed="true" title="Hide layer 1">${visibilityIcon}</button></div>
<label class="cell-field"><span class="cell-sr-only">Wavelength</span><select id="cell-wave" aria-label="Wavelength" disabled><option>Loading…</option></select></label>
<details class="cell-base-options cell-layer-options"><summary>Options</summary><label class="cell-toggle"><span>Nearby wavelengths</span><input type="checkbox" id="cell-nearby" title="Include nearby wavelengths from the same detector band"></label><div id="cell-mix" hidden><div id="cell-mix-chips"></div><div class="cell-add-wave"><select id="cell-mix-add" aria-label="Add wavelength"></select><button id="cell-mix-button">Add</button></div></div></details>
</section><div id="cell-layer-list" aria-label="Added layers"></div><p id="cell-wavelength-limit" class="cell-wavelength-note" hidden>Maximum of five layers.</p></section>
<details class="cell-disclosure cell-adjustments"><summary>Image adjustments</summary><div class="cell-tools">
<label class="cell-field"><span>Contrast</span><input id="cell-contrast" aria-label="Contrast" type="range" min=".4" max="2.5" step=".05" value="1"></label>
<label class="cell-field">Denoise<select id="cell-noise" aria-label="Denoise"><option value="0">Off</option><option value="1">Low</option><option value="2" selected>High</option></select></label>
<label class="cell-toggle"><span>Background removal</span><input type="checkbox" id="cell-background" checked></label>
<details class="cell-more-options"><summary>More adjustments</summary>
<label class="cell-field">Display<select id="cell-colour" aria-label="Image colour"><option value="gray">Grayscale</option><option value="colour">False colour</option></select></label>
<label class="cell-field">Framing<select id="cell-framing" aria-label="Image framing"><option value="shared">Shared coverage</option><option value="full">Full field</option></select></label><output id="cell-field-width"></output>
<label class="cell-toggle"><span>Quality mask</span><input type="checkbox" id="cell-quality" checked></label><label class="cell-toggle"><span>Smooth pixels</span><input type="checkbox" id="cell-interpolate" checked></label><label class="cell-toggle"><span>Repair small gaps</span><input type="checkbox" id="cell-repair" checked></label>
<button id="cell-combine" class="cell-combine" disabled>Combine exposures</button><output id="cell-combine-status"></output></details></div></details>
<details class="cell-disclosure motion-tools" ${tracking?'open':''}><summary>Motion tracking</summary><label class="cell-toggle"><span>Mark positions</span><input id="motion-mark" type="checkbox"></label><label class="cell-toggle"><span>Track from a click</span><input id="motion-auto" type="checkbox" checked></label><p class="motion-help">Click an object to mark or track it.</p><output id="motion-progress" role="status"></output><button id="motion-stop" hidden>Stop tracking</button><output id="motion-summary"></output>
<details class="cell-more-options"><summary>Examples &amp; records</summary><label class="cell-field">Motion demos<select id="motion-demo" aria-label="Motion demos"></select></label><p id="motion-example-note" class="motion-help"></p><p class="motion-help">Tracking is approximate; blends and saturated sources can mislead it.</p><details><summary>Marked positions</summary><pre id="motion-points"></pre></details><div class="motion-actions"><button id="motion-clear">Clear marks</button><button id="motion-export" disabled>Export positions</button></div></details></details>
<details class="cell-disclosure cell-source-details"><summary>Observation details</summary><div class="cell-observation-info" id="cell-info"></div><a id="cell-fits" class="cell-download" hidden target="_blank" rel="noreferrer">Download FITS ↗</a></details>
</div><footer class="cell-rail-footer"><div class="cell-document-actions"><button id="cell-document" type="button" disabled>Document cell</button><a href="/saved-cells/">Saved cells</a></div><p id="cell-document-status" role="status"></p></footer></aside>`;}
